INSERT INTO apis_proyectos (nombre, tipo, equipo_responsable, descripcion) VALUES
('api-personas',        'api',        'Equipo Personas',          'API REST que consulta y actualiza datos básicos de personas.'),
('api-clientes',        'api',        'Equipo Clientes',          'API REST con el perfil, los contactos y las preferencias de los clientes.'),
('api-pagos',           'api',        'Equipo Pagos',             'API REST que registra y consulta pagos y transferencias.'),
('api-cuentas',         'api',        'Equipo Cuentas',           'API REST de saldos, movimientos y estados de cuenta.'),
('api-notificaciones',  'api',        'Equipo Canales Digitales', 'API que envía notificaciones por correo, SMS y notificaciones push.'),
('api-autenticacion',   'api',        'Equipo Seguridad',         'API de inicio de sesión, tokens de acceso y segundo factor.'),
('bd-personas',         'base_datos', 'Equipo Datos',             'Base de datos PostgreSQL con el maestro de personas.'),
('bd-clientes',         'base_datos', 'Equipo Datos',             'Base de datos Azure SQL con el perfil de clientes.'),
('bd-transacciones',    'base_datos', 'Equipo Datos',             'Base de datos Azure SQL con las transacciones de pagos y cuentas.'),
('bd-reportes',         'base_datos', 'Equipo Datos',             'Base de datos PostgreSQL de reportes y consultas analíticas.'),
('bd-auditoria',        'base_datos', 'Equipo Seguridad',         'Base de datos con los registros de auditoría de accesos y cambios.'),
('app-banca-web',       'aplicacion', 'Equipo Canales Digitales', 'Aplicación web de banca en línea para clientes.'),
('app-banca-movil',     'aplicacion', 'Equipo Canales Digitales', 'Aplicación móvil de banca para clientes en Android e iOS.'),
('portal-empleados',    'aplicacion', 'Equipo Plataforma',        'Portal interno para empleados con solicitudes y herramientas internas.'),
('app-backoffice',      'aplicacion', 'Equipo Plataforma',        'Aplicación de operación interna para conciliación y soporte a clientes.');
INSERT INTO documentos (titulo, tipo, contenido) VALUES
('Modelo operativo de gestión de incidentes', 'modelo_operativo',
INSERT INTO soluciones_codigo (repositorio, titulo, descripcion, aplicativo_id) VALUES
('org/api-personas', 'Corrección de error 500 por valores nulos en la consulta de personas',
INSERT INTO tickets (titulo, detalle_problema, equipo_responsable, evidencias, aplicativo_id, ambiente, detalle_solucion, estado, creado_en) VALUES
('Error 500 en api-personas: valores nulos en la consulta', 'Se reporta que en api-personas las consultas devuelven HTTP 500 cuando algún campo opcional llega nulo.', 'Equipo Personas', 'NullPointerException en el mapeador de respuesta | HTTP 500 en GET /personas/{id}', (SELECT id FROM apis_proyectos WHERE nombre = 'api-personas'), 'produccion', NULL, 'abierto', now() - interval '4 days 23 hours'),
('Error 500 en api-autenticacion: pool de conexiones agotado', 'Se reporta que en api-autenticacion hay intermitencia con HTTP 500 en horas pico porque todas las conexiones al pool de base de datos están ocupadas.', 'Equipo Seguridad', 'Connection is not available, request timed out after 30000ms | POST /token', (SELECT id FROM apis_proyectos WHERE nombre = 'api-autenticacion'), 'produccion', 'Se amplió el pool de conexiones y se definió un tiempo máximo de uso por conexión.', 'resuelto', now() - interval '87 days 23 hours'),
('Error 500 en api-notificaciones: falla tras despliegue', 'Un usuario informó que en api-notificaciones el servicio responde HTTP 500 en todos los endpoints desde el último despliegue.', 'Equipo Canales Digitales', 'Error al iniciar: variable de entorno DB_URL no definida | versión 2.4.1', (SELECT id FROM apis_proyectos WHERE nombre = 'api-notificaciones'), 'produccion', NULL, 'abierto', now() - interval '5 days 0 hours'),
('Error 500 en api-cuentas: timeout en dependencia', 'Se reporta que en api-cuentas el servicio devuelve HTTP 500 porque una dependencia interna no responde a tiempo.', 'Equipo Cuentas', 'ReadTimeoutException tras 10 s llamando a servicio interno | GET /cuentas/{id}/movimientos', (SELECT id FROM apis_proyectos WHERE nombre = 'api-cuentas'), 'certificacion', 'Se definió un tiempo máximo de 3 s y reintentos con espera exponencial.', 'resuelto', now() - interval '72 days 6 hours'),
('Error 500 en api-pagos: falta de memoria del servicio', 'Un usuario informó que en api-pagos el servicio se reinicia y responde HTTP 500 por falta de memoria.', 'Equipo Pagos', 'OutOfMemoryError: Java heap space | contenedor reiniciado 6 veces en 1 hora', (SELECT id FROM apis_proyectos WHERE nombre = 'api-pagos'), 'certificacion', 'Se paginó la consulta de mayor volumen y se aumentó el límite de memoria del contenedor.', 'cerrado', now() - interval '29 days 14 hours'),
('Error 500 en api-clientes: solicitudes con caracteres especiales', 'Se reporta que en api-clientes algunos clientes reciben HTTP 500 al enviar datos con tildes o la letra ñ.', 'Equipo Clientes', 'JsonParseException: Unexpected character | GET /clientes/{id}', (SELECT id FROM apis_proyectos WHERE nombre = 'api-clientes'), 'produccion', 'En curso: Se configuró UTF-8 en el filtro de entrada y se devuelve 400 con un mensaje claro para solicitudes inválidas.', 'en_progreso', now() - interval '21 days 22 hours'),
('Error 500 en api-personas: certificado TLS vencido', 'Soporte indica que en api-personas las llamadas a un servicio interno fallan con HTTP 500 por un certificado vencido.', 'Equipo Personas', 'SSLHandshakeException: certificate expired | GET /personas/{id}', (SELECT id FROM apis_proyectos WHERE nombre = 'api-personas'), 'produccion', 'Se renovó el certificado y se agregó una alerta 30 días antes del vencimiento.', 'resuelto', now() - interval '44 days 3 hours'),
('Error 500 en api-autenticacion: columna faltante en la base', 'Monitoreo detectó que en api-autenticacion tras un cambio en la base de datos falta una columna que el servicio espera y responde HTTP 500.', 'Equipo Seguridad', 'PSQLException: column "estado_civil" does not exist | POST /token', (SELECT id FROM apis_proyectos WHERE nombre = 'api-autenticacion'), 'certificacion', 'Se aplicó el script de migración pendiente y se incluyó en el pipeline de despliegue.', 'resuelto', now() - interval '78 days 8 hours'),
('Error 500 en api-autenticacion: valores nulos en la consulta', 'Se reporta que en api-autenticacion las consultas devuelven HTTP 500 cuando algún campo opcional llega nulo.', 'Equipo Seguridad', 'NullPointerException en el mapeador de respuesta | HTTP 500 en POST /token', (SELECT id FROM apis_proyectos WHERE nombre = 'api-autenticacion'), 'certificacion', 'Se validan los campos opcionales antes de armar la respuesta y se devuelve 404 si el registro no existe.', 'cerrado', now() - interval '49 days 2 hours'),
